template<class T> using pq_min = priority_queue<T, vector<T>, greater<T>>;
template<class T> using pq_max = priority_queue<T, vector<T>, less<T>>;
#define int long long

void solve();

signed main() {
#ifdef LOCAL
    freopen("input.txt", "r", stdin);
    freopen("output.txt", "w", stdout);
#endif
    ios::sync_with_stdio(false);
    cin.tie(0);
    cout.tie(0);
    ll q = 1;
    cin >> q;
    while (q--) {
        solve();
        //cout << "\n";
    }
}

vector<vector<int>> g;
vector<int> a;
int h;
vector<bool> us;
int cnt1;
vector<int> T;

void dfs1(int v, int pr) {
    T.push_back(v);
    cnt1++;
    for (auto to: g[v]) {
        if (to != pr && !us[to]) {
            dfs1(to, v);
        }
    }
}

int dfs(int v, int pr) {
    bool p = true;
    int cnt = 1;
    for (auto to: g[v]) {
        if (to != pr && !us[to]) {
            auto u = dfs(to, v);
            if (u > cnt1 / 2) {
                p = false;
            }
            cnt += u;
        }
    }
    if (p && (cnt1 &mdash; cnt) <= cnt1 / 2) {
        h = v;
    }
    return cnt;
}

int E = 0;

vector<int> ans;
vector<vector<int>> mn;
vector<int> col;
vector<int> sz;
vector<int> W;

void dfs(int v, int pr, vector<int> s, int an, int o, int mx) {
    sz[v] = o;
    col[v] = E;
    W[v] = W[pr];
    for (int i = 0; i < 20; ++i) {  
        mn[v][i] = mn[pr][i];
    }
    for (int i = 0; i < 20; ++i) {
        if ((a[v] >> i) & 1) {
            if (mn[v][i] != INF) {
                W[v] = min(W[v], o);
            }
            mn[v][i] = min(mn[v][i], o);
            mx = max(mx, s[i]);
            s[i] = o;
        }
    }
    an += o &mdash; mx;
    ans[v] = an;
    for (auto to: g[v]) {
        if (to != pr && !us[to]) {
            dfs(to, v, s, an, o + 1, mx);
        }
    }
}

vector<vector<pair<int, int>>> que;
vector<int> ANS;

void rec(int v) {
    T.clear();
    cnt1 = 0;
    dfs1(v, -1);
    dfs(v, -1);
    v = h;
    us[v] = true;
    mn[v] = vector<int>(20, INF);
    int S = E;
    W[v] = INF;
    for (auto to: g[v]) {
        if (!us[to]) {
            E++;
            vector<int> s(20, 0);
            dfs(to, v, s, 0, 1, 0);
        }
    }
    ans[v] = 0;
    ++E;
    col[v] = E;
    for (auto x: T) {
        for (auto [y, id]: que[x]) {
            if (col[x] != col[y] && col[x] > S && col[y] > S) {
                ANS[id] = ans[x] + ans[y];
                if (x == v) {
                    int MN = min(W[y], sz[y] + 1);
                    for (int i = 0; i < 20; ++i) {
                        if ((a[v] >> i) & 1) {
                            MN = min(MN, mn[y][i]);
                        }
                    }
                    ANS[id] += MN;
                } else if (y == v) {
                    int MN = min(W[x], sz[x] + 1);
                    for (int i = 0; i < 20; ++i) {
                        if ((a[v] >> i) & 1) {
                            MN = min(MN, mn[x][i]);
                        }
                    }
                    ANS[id] += MN;
                } else {
                    vector<pair<int, int>> upd;
                    for (int i = 0; i < 20; ++i) {
                        if (mn[x][i] != INF) {
                            upd.push_back({mn[x][i], i});
                        }
                    }
                    int e = min(W[y], sz[y] + 1);
                    for (int i = 0; i < 20; ++i) {
                        if ((a[v] >> i) & 1) {
                            e = min(e, mn[y][i]);
                        }
                    }
                    sort(upd.begin(), upd.end());
                    int p = 0;
                    bool flag = true;
                    for (int i = 0; i < upd.size(); ++i) {
                        if (upd[i].first >= W[x]) {
                            ANS[id] += (W[x] &mdash; p) * e;
                            flag = false;
                            break;
                        }
                        ANS[id] += (upd[i].first &mdash; p) * e;
                        if ((a[v] >> upd[i].second) & 1) {
                            flag = false;
                            break;
                        }
                        e = min(e, mn[y][upd[i].second]);
                        p = upd[i].first;
                    }
                    if (flag) {
                        ANS[id] += (min(W[x], sz[x] + 1) &mdash; p) * e;
                    }
                }
            }
        }
    }
    for (int i = 0; i < g[v].size(); ++i) {
        int to = g[v][i];
        if (!us[to]) {
            rec(to);
        }
    }
}


void solve() {
    int n, q;
    cin >> n >> q;
    sz.clear();
    W.clear();
    W.resize(n);
    sz.resize(n);
    ans.clear();
    ANS.clear();
    ANS.resize(q, -1);
    mn.clear();
    ans.resize(n);
    mn.resize(n, vector<int>(20));
    a.clear();
    us.clear();
    us.resize(n);
    a.resize(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }
    g.clear();
    col.clear();
    col.resize(n);
    que.clear();
    que.resize(n);
    g.resize(n);
    for (int i = 0; i < n &mdash; 1; ++i) {
        int u, v;
        cin >> u >> v;
        --u;
        --v;
        g[u].push_back(v);
        g[v].push_back(u);
    }
    for (int i = 0; i < q; ++i) {
        int x, y;
        cin >> x >> y;
        --x;
        --y;
        que[x].push_back({y, i});
    }
    rec(0);
    for (int i = 0; i < q; ++i) {
        if (ANS[i] == -1) {
            exit(-1);
        }
        cout << ANS[i] << "\n";
    }
}
